def handle(raw):
    req = parse_request(raw)
    if not isinstance(req, dict):
        die("E_SCHEMA")
    if set(req.keys()) != TOP_KEYS:
        die("E_SCHEMA")
    if not (is_int(req["version"]) and req["version"] == 1):
        die("E_SCHEMA")
    K = req["window"]
    if not (is_int(K) and 1 <= K <= 8):
        die("E_SCHEMA")
    fields = validate_schema(req["schema"])
    width_limit, min_support, min_witness = validate_policy(req["policy"])
    atoms = req["atoms"]
    if not isinstance(atoms, list) or not (0 <= len(atoms) <= 20):
        die("E_SCHEMA")
    fbn = {}
    for idx, fld in enumerate(fields):
        fbn[fld["name"]] = fld
        fld["index"] = idx
    for atom in atoms:
        validate_atom(atom, K, fbn)

    counters = {"traces": 0, "rows": 0}
    seen_ids = set()
    train_traces = validate_traces(req["train"], fields, seen_ids, counters)
    probe_traces = validate_traces(req["probes"], fields, seen_ids, counters)
    query_traces = validate_traces(req["queries"], fields, seen_ids, counters)

    train_sources = []
    train_src_seen = set()
    for tr in train_traces:
        if tr["source"] not in train_src_seen:
            train_src_seen.add(tr["source"])
            train_sources.append(tr["source"])
    if len(train_sources) > MAX_TRAIN_SOURCES:
        die("E_SCHEMA")

    train_ctx = build_contexts(train_traces, K)
    probe_ctx = build_contexts(probe_traces, K)
    query_ctx = build_contexts(query_traces, K)
    if len(train_ctx) > MAX_TRAIN_CTX:
        die("E_SCHEMA")
    if len(probe_ctx) > MAX_PROBE_CTX:
        die("E_SCHEMA")
    if len(query_ctx) > MAX_QUERY_CTX:
        die("E_SCHEMA")

    natoms = len(atoms)
    fidx = {}
    for fld in fields:
        fidx[fld["name"]] = fld["index"]
    fns = compile_atoms(atoms, fidx)

    ntrain = len(train_ctx)
    nprobe = len(probe_ctx)
    nquery = len(query_ctx)

    train_bits = eval_partition(train_ctx, fns) if natoms else []
    probe_bits = eval_partition(probe_ctx, fns) if natoms else []
    query_bits = eval_partition(query_ctx, fns) if natoms else []

    classes = {}
    if natoms and len(train_sources) >= 1 and nprobe >= 1:
        classes = mine(train_ctx, train_sources, train_bits, probe_bits,
                       query_bits, natoms, width_limit, min_support, min_witness,
                       ntrain, nprobe, nquery)

    classes_out = []
    for sig, entry in classes.items():
        count, rep, _orset, _andset = entry
        classes_out.append({
            "signature": format_signature(sig, nprobe),
            "members": count,
            "representative": {"or": [{"atom": li >> 1, "negated": (li & 1) == 1}
                                      for li in rep]},
        })

    counter_must = BitCounter()
    counter_may = BitCounter()
    full_q = (1 << nquery) - 1
    for entry in classes.values():
        counter_must.add(full_q ^ entry[2])
        counter_may.add(full_q ^ entry[3])

    queries_out = []
    for idx, ctx in enumerate(query_ctx):
        must = counter_must.count_at(idx)
        may = counter_may.count_at(idx)
        if must > 0:
            status = "violating"
        elif may > 0:
            status = "ambiguous"
        else:
            status = "consistent"
        queries_out.append({"trace": ctx[1], "end": ctx[3], "must": must,
                            "may": may, "status": status})

    return {"version": 1, "classes": classes_out, "queries": queries_out}


